<?php require_once __DIR__.'/../includes/auth.php';require_admin();require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/topping_price.php';$pdo=db();$id=(int)($_GET['id']??0);$t=['id'=>0,'nombre'=>'','precio'=>'0.00','orden'=>0,'activo'=>0];if($id){$s=$pdo->prepare('SELECT * FROM toppings WHERE id=?');$s->execute([$id]);$t=$s->fetch()?:$t;}
$t['precio_operativo']=topping_effective_price($pdo,$t);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if($id){$s=$pdo->prepare('UPDATE toppings SET nombre=?,precio=?,orden=?,activo=? WHERE id=?');$s->execute([trim($_POST['nombre']),max(0,(float)$_POST['precio']),(int)$_POST['orden'],isset($_POST['activo'])?1:0,$id]);}else{$s=$pdo->prepare('INSERT INTO toppings(nombre,precio,orden,activo) VALUES(?,?,?,?)');$s->execute([trim($_POST['nombre']),max(0,(float)$_POST['precio']),(int)$_POST['orden'],isset($_POST['activo'])?1:0]);}header('Location:index.php#toppings');exit;}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$id?'Editar':'Nuevo'?> complemento · Snackliciosos</title><link rel="stylesheet" href="style.css?v=11"><link rel="stylesheet" href="catalogo.css?v=12"></head><body><?php require __DIR__.'/sidebar.php'; ?><main class="wrap admin-content"><section class="hero"><div><span class="eyebrow">COMPLEMENTOS · CASCADA</span><h1><?=$id?'Editar':'Nuevo'?> topping</h1><p>Configura el complemento en pocos pasos. Los precios se reflejan en el TPV.</p></div></section><section class="card cascade-card"><form class="form" method="post" id="toppingWizard"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="wizard-progress"><span class="wizard-step-dot active"></span><span class="wizard-step-dot"></span><span class="wizard-step-dot"></span></div><div class="wizard-pane active"><span class="eyebrow">01 · COMPLEMENTO</span><h2 class="wizard-question">¿Qué topping es?</h2><p class="wizard-help">Escribe el nombre que verá el operador.</p><label>Nombre<input id="tName" name="nombre" value="<?=h($t['nombre'])?>" required autofocus placeholder="Ej. Oreo"></label><div class="wizard-actions"><a class="btn btn-light" href="index.php#toppings">Cancelar</a><button class="btn btn-primary" type="button" data-next>Continuar →</button></div></div><div class="wizard-pane"><span class="eyebrow">02 · PRECIO</span><h2 class="wizard-question">¿Cuánto se cobra?</h2><p class="wizard-help">Este precio se suma al producto cuando corresponda según la regla de toppings.</p><label>Precio<input id="tPrice" name="precio" type="number" step="0.01" min="0" value="<?=h(number_format((float)$t['precio_operativo'],2,'.',''))?>" required></label><div class="wizard-summary">Precio operativo: <span class="live-price" id="tPricePreview"><?=money($t['precio_operativo'])?></span></div><label>Orden<input name="orden" type="number" value="<?=h((string)$t['orden'])?>"><span class="field-hint">0 = dejar que el orden existente determine su posición.</span></label><div class="wizard-actions"><button class="btn btn-light" type="button" data-prev>← Atrás</button><button class="btn btn-primary" type="button" data-next>Continuar →</button></div></div><div class="wizard-pane"><span class="eyebrow">03 · DISPONIBILIDAD</span><h2 class="wizard-question">¿Está disponible?</h2><p class="wizard-help">Los toppings inactivos no deben ofrecerse para selección.</p><label class="check"><input type="checkbox" name="activo" <?=$t['activo']?'checked':''?>> Topping activo</label><div class="wizard-summary"><strong id="tFinal"><?=h($t['nombre']?:'Nuevo topping')?></strong><br><span id="tFinalPrice"><?=money($t['precio_operativo'])?></span></div><div class="wizard-actions"><button class="btn btn-light" type="button" data-prev>← Atrás</button><button class="btn btn-primary" type="submit">✓ GUARDAR COMPLEMENTO</button></div></div></form></section></main><script>(function(){const f=document.getElementById('toppingWizard'),p=[...f.querySelectorAll('.wizard-pane')],d=[...f.querySelectorAll('.wizard-step-dot')];let i=0;const n=document.getElementById('tName'),pr=document.getElementById('tPrice'),pv=document.getElementById('tPricePreview');function money(v){return new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(parseFloat(v)||0)}function ok(){for(const x of p[i].querySelectorAll('input[required]'))if(!x.checkValidity()){x.reportValidity();return false}return true}function r(){p.forEach((x,n)=>x.classList.toggle('active',n===i));d.forEach((x,n)=>x.classList.toggle('active',n<=i));document.getElementById('tFinal').textContent=n.value||'Nuevo topping';document.getElementById('tFinalPrice').textContent=money(pr.value)}f.querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>{if(ok()&&i<p.length-1){i++;r()}});f.querySelectorAll('[data-prev]').forEach(b=>b.onclick=()=>{if(i){i--;r()}});pr.oninput=()=>pv.textContent=money(pr.value);r()})();</script></body></html>
